from abc import ABC, abstractmethod
from pathlib import Path
from typing import Dict, Optional


class AbstractSidecarStore(ABC):
    """Abstract interface for sidecar persistence."""

    @abstractmethod
    def save(self, image_path: str, result: Dict) -> str:
        """Persist an extraction result dict and return the sidecar path."""
        ...

    @abstractmethod
    def load(self, image_path: str) -> Optional[Dict]:
        """Read and parse a sidecar JSON for the given image, or None."""
        ...

    @abstractmethod
    def exists(self, image_path: str) -> bool:
        """Return True if a sidecar exists for the given image."""
        ...

    @classmethod
    @abstractmethod
    def sidecar_path(cls, image_path: str) -> Path:
        """Return the expected sidecar JSON path for a given image."""
        ...

import json
import logging
import os
import tempfile
from pathlib import Path
from typing import Dict, Optional

from .store import AbstractSidecarStore
from .database import FeaturesDatabase

logger = logging.getLogger(__name__)


class SidecarWriter(AbstractSidecarStore):
    """Write extraction results as a sidecar JSON file next to the source image.

    Output goes to ``<image_dir>/.open-photo-agent/data/<image>.json`` using
    an atomic tempfile+replace pattern.
    """

    @classmethod
    def sidecar_path(cls, image_path: str) -> Path:
        """Return the expected sidecar JSON path for a given image."""
        img = Path(image_path)
        return img.parent / ".open-photo-agent" / "data" / f"{img.name}.json"

    @classmethod
    def load(cls, image_path: str) -> Optional[Dict]:
        """Read and parse a sidecar JSON for the given image.

        Args:
            image_path: Absolute path to the source image file.

        Returns:
            The parsed dict if the sidecar exists and is valid JSON, or None.
        """
        sp = cls.sidecar_path(image_path)
        if not sp.is_file():
            return None
        try:
            return json.loads(sp.read_text(encoding="utf-8"))
        except (json.JSONDecodeError, OSError):
            return None

    def exists(self, image_path: str) -> bool:
        """Return True if a sidecar exists for the given image."""
        return self.sidecar_path(image_path).is_file()

    def save(self, image_path: str, result: Dict) -> str:
        """Persist an extraction result dict to the sidecar directory.

        Args:
            image_path: Absolute path to the source image file.
            result: A dict containing extraction result fields (success,
                response, parsed, model, durations, error, etc.).

        Returns:
            The absolute path to the written sidecar JSON file.
        """
        img = Path(image_path)
        sidecar_dir = img.parent / ".open-photo-agent" / "data"

        try:
            sidecar_dir.mkdir(parents=True, exist_ok=True)
        except OSError as e:
            logger.error(f"Failed to create sidecar directory {sidecar_dir}: {e}")
            raise

        sidecar_path = self.sidecar_path(image_path)
        payload = {
            "image_path": str(img),
            "success": result.get("success", False),
            "model": result.get("model"),
            "prompt": result.get("prompt"),
            "response": result.get("response"),
            "parsed": result.get("parsed"),
            "total_duration_ms": result.get("total_duration_ms"),
            "eval_count": result.get("eval_count"),
            "done": result.get("done"),
            "error": result.get("error"),
            "error_code": result.get("error_code"),
        }
        payload = {k: v for k, v in payload.items() if v is not None}

        try:
            fd, tmp_path = tempfile.mkstemp(
                suffix=".json", prefix=f".{img.name}.", dir=str(sidecar_dir)
            )
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                json.dump(payload, f, indent=2, ensure_ascii=False)
            os.replace(tmp_path, sidecar_path)
        except OSError as e:
            logger.error(f"Failed to write sidecar {sidecar_path}: {e}")
            raise

        logger.info(f"Saved sidecar: {sidecar_path}")
        return str(sidecar_path)


class DatabaseSidecarStore(AbstractSidecarStore):
    """Write extraction results to the per-folder SQLite ``features.db``.

    Replaces individual JSON sidecars with upserts into the ``raw_features``
    table, enabling fast querying and concurrent reads.
    """

    def __init__(self):
        self._dbs: Dict[str, FeaturesDatabase] = {}

    def _get_db(self, image_path: str) -> FeaturesDatabase:
        folder = str(Path(image_path).parent)
        if folder not in self._dbs:
            db_path = FeaturesDatabase.default_db_path(folder)
            self._dbs[folder] = FeaturesDatabase(db_path)
        return self._dbs[folder]

    @classmethod
    def sidecar_path(cls, image_path: str) -> Path:
        """Return the expected database path for a given image."""
        return FeaturesDatabase.default_db_path(Path(image_path).parent)

    def save(self, image_path: str, result: Dict) -> str:
        """Persist an extraction result dict to the folder's features.db.

        Returns:
            The absolute path to the database file.
        """
        db = self._get_db(image_path)
        db.save_extraction(image_path, result)
        return str(db.db_path)

    def load(self, image_path: str) -> Optional[Dict]:
        """Read an extraction result for the given image from the DB."""
        db = self._get_db(image_path)
        return db.get_extraction(image_path)

    def exists(self, image_path: str) -> bool:
        """Return True if a DB row exists for the given image."""
        db = self._get_db(image_path)
        return db.is_processed(image_path)

from abc import ABC, abstractmethod
from typing import List, Optional

from src.sidecar import AbstractSidecarStore, get_writer
from .result import ProcessingResult


class ResultSaver(ABC):
    """Abstract sink for processing results."""

    @abstractmethod
    def save(self, result: ProcessingResult) -> None:
        """Persist (or collect) one ProcessingResult."""
        ...


class SidecarResultSaver(ResultSaver):
    """Write each result as a sidecar JSON file next to the source image."""

    def __init__(self, store: Optional[AbstractSidecarStore] = None):
        """Initialise with the given sidecar store (defaults to singleton)."""
        self._writer = store or get_writer()

    def save(self, result: ProcessingResult) -> None:
        data = result.as_dict()
        if result.image_path:
            self._writer.save(result.image_path, data)


class CollectingSidecarSaver(SidecarResultSaver):
    """Like SidecarResultSaver but also accumulates results in a list."""

    def __init__(self, store: Optional[AbstractSidecarStore] = None):
        super().__init__(store=store)
        self.results: List[dict] = []

    def save(self, result: ProcessingResult) -> None:
        super().save(result)
        self.results.append(result.as_dict())


class InMemoryCollector(ResultSaver):
    """Accumulate ProcessingResult objects in memory (no sidecar write)."""

    def __init__(self):
        self.results: List[ProcessingResult] = []

    def save(self, result: ProcessingResult) -> None:
        self.results.append(result)


class NoOpResultSaver(ResultSaver):
    """Discards all results (useful for testing or dry-runs)."""

    def save(self, result: ProcessingResult) -> None:
        pass

from datetime import datetime, timezone
from pathlib import Path
from typing import List, Optional, Set, Tuple, Dict
import logging

from src.sidecar.database import FeaturesDatabase
from src.sidecar.writer import SidecarWriter

logger = logging.getLogger(__name__)

# module-level cache: folder -> (cache_key, processed_set)
_PROCESSED_SET_CACHE: Dict[str, Tuple[Tuple, Set[str]]] = {}


def _db_cache_key(image_dir: str) -> Tuple:
    """Return a cache key that changes if any sidecar data source is created,
    deleted, or modified."""
    key_parts = []
    for p in (
        FeaturesDatabase.default_db_path(image_dir),
        Path(image_dir) / ".open-photo-agent" / "wal.jsonl",
        Path(image_dir) / ".open-photo-agent" / "data",
    ):
        try:
            if p.exists():
                st = p.stat()
                key_parts.append((str(p), True, st.st_mtime, st.st_size))
            else:
                key_parts.append((str(p), False, 0, 0))
        except OSError:
            key_parts.append((str(p), False, 0, 0))
    return tuple(key_parts)


def clear_processed_cache(image_dir: str) -> None:
    """Remove cached processed-set data for a folder, forcing a re-read."""
    _PROCESSED_SET_CACHE.pop(image_dir, None)


class PhotoList:
    """Handles discovery and listing of photos in specified folders."""

    def __init__(self, recursive: bool = True, extensions: Set[str] = None):
        """Initialise the photo discovery helper.

        Args:
            recursive: If True, scan sub-directories recursively.
            extensions: Set of lowercase file extensions to include.
                Defaults to common image formats.
        """
        self.recursive = recursive
        self.extensions = extensions or {".jpg", ".jpeg", ".png", ".webp", ".gif", ".bmp", ".tiff", ".tif", ".heic", ".heif"}

    def list_photos(
        self,
        paths: List[str],
        limit: Optional[int] = None,
        exclude_processed_from: Optional[str] = None,
    ) -> List[str]:
        """
        Expand directories into image file paths.

        Args:
            paths: List of paths (files or directories).
            limit: If set, return at most this many image paths.
            exclude_processed_from: If set to a directory path, use WAL,
                DB, or legacy sidecar fallback to exclude completed images.

        Returns:
            List of absolute image file paths.
        """
        images = []
        logger.info(f"Listing photos for paths: {paths}")
        for p in paths:
            path = Path(p).absolute()
            logger.info(f"Checking path: {path} (Exists: {path.exists()}, IsDir: {path.is_dir()})")
            if path.is_dir():
                if self.recursive:
                    candidates = list(path.rglob("*"))
                    logger.info(f"Found {len(candidates)} total candidates in {path} (recursive)")
                else:
                    candidates = list(path.iterdir())
                    logger.info(f"Found {len(candidates)} total candidates in {path} (non-recursive)")
                for child in candidates:
                    if child.is_file() and child.suffix.lower() in self.extensions:
                        images.append(str(child))
            elif path.is_file():
                if path.suffix.lower() in self.extensions:
                    images.append(str(path))
                else:
                    logger.warning(f"File is not a supported image: {p}")
            else:
                logger.warning(f"Path not found: {p}")

        logger.info(f"Total images discovered: {len(images)}")

        if exclude_processed_from:
            processed = self._load_processed_set(exclude_processed_from)
            if processed:
                images = [img for img in images if img not in processed]
                logger.info(f"After excluding {len(processed)} processed: {len(images)} remaining")

        if limit is not None:
            images = images[:limit]
            logger.info(f"After limiting to {limit}: {len(images)} remaining")

        return images

    @staticmethod
    def _load_processed_set(image_dir: str) -> set:
        """Build a set of already-processed image paths from WAL, DB, or legacy sidecars.

        Prefers WAL data. Falls back to the ``features.db`` rows. Finally
        scans legacy sidecar JSONs. If sidecars are found and no WAL
        exists, auto-migrates the sidecar entries into the WAL.
        Results are cached by folder and invalidated only when WAL, DB,
        or sidecar data changes on disk.
        """
        cached = _PROCESSED_SET_CACHE.get(image_dir)
        current_key = _db_cache_key(image_dir)
        if cached is not None and cached[0] == current_key:
            return cached[1]

        from src.wal import WriteAheadLog

        wal = WriteAheadLog(image_dir)
        processed: Set[str] = set()

        if wal._path.exists():
            completed = wal.get_completed_set()
            if completed:
                processed = completed

        db_path = FeaturesDatabase.default_db_path(image_dir)
        if not processed and db_path.exists():
            try:
                db = FeaturesDatabase(db_path)
                extractions = db.list_extractions()
                db.close()
                processed = {
                    ex["image_path"] for ex in extractions
                    if ex.get("image_path")
                }
            except Exception:
                logger.warning("Failed to read features DB for %s", image_dir, exc_info=True)

        # Legacy JSON sidecar fallback
        sidecar_dir = Path(image_dir) / ".open-photo-agent" / "data"
        if not processed and sidecar_dir.is_dir():
            parent_dir = sidecar_dir.parent.parent
            for f in sidecar_dir.iterdir():
                if f.suffix == ".json":
                    image_name = f.stem
                    image_path = str(parent_dir / image_name)
                    data = SidecarWriter.load(image_path)
                    if data:
                        img_path = data.get("image_path")
                        if img_path:
                            processed.add(img_path)

            if processed and not wal._path.exists():
                logger.info("Auto-migrating %d sidecars to WAL in %s", len(processed), image_dir)
                microbatch_id = f"migrate-{datetime.now(timezone.utc).strftime('%Y%m%d-%H%M%S')}"
                for img_path in processed:
                    sidecar_name = Path(img_path).name + ".json"
                    full_sidecar = str(sidecar_dir / sidecar_name)
                    wal.append(img_path, "completed", microbatch_id, sidecar_path=full_sidecar)

        _PROCESSED_SET_CACHE[image_dir] = (current_key, processed)
        return processed
